		{
			String Word = Sf.nextLine();
			int Count = 0;
			int D = 0;
			if (Word.length()>1)
				D=letterDiff(Word.charAt(0),Word.charAt(1));
			for(int x=0;x<Word.length()-1;x++)
				if(letterDiff(Word.charAt(x),Word.charAt(x+1))==D)
